return {["table"]={{"ABRA",{["value"]={["kind"]="PSÍQUICO",["text"]="Sente ataques que<NEXT>estão por vir e se<NEXT>teletransporta",["text2"]="para um lugar<NEXT>seguro antes de<NEXT>ser atingido."}}},{"AERODACTYL",{["value"]={["kind"]="FÓSSIL",["text"]="Um feroz POKéMON<NEXT>de um passado<NEXT>distante. Parece",["text2"]="que voava abrindo<NEXT>as asas e<NEXT>planando."}}},{"AIPOM",{["value"]={["kind"]="CAUDA LONGA",["text"]="Sua cauda é tão<NEXT>forte que pode<NEXT>agarrar um galho e",["text2"]="sustentar todo o<NEXT>corpo no ar."}}},{"ALAKAZAM",{["value"]={["kind"]="PSÍQUICO",["text"]="Fechar os olhos<NEXT>aguça seus outros<NEXT>sentidos. Assim,",["text2"]="usa suas<NEXT>habilidades ao<NEXT>máximo."}}},{"AMPHAROS",{["value"]={["kind"]="LUZ",["text"]="A ponta da cauda<NEXT>brilha tanto que é<NEXT>vista de longe.",["text2"]="Serve de farol<NEXT>para pessoas<NEXT>perdidas."}}},{"ARBOK",{["value"]={["kind"]="NAJA",["text"]="Paralisa a presa<NEXT>com o desenho de<NEXT>rosto no ventre.",["text2"]="Depois a envolve e<NEXT>envenena."}}},{"ARCANINE",{["value"]={["kind"]="LENDÁRIO",["text"]="Este lendário<NEXT>POKéMON chinês é<NEXT>magnífico. Sua",["text2"]="grande juba<NEXT>encanta muita<NEXT>gente."}}},{"ARIADOS",{["value"]={["kind"]="PERNA LONGA",["text"]="Solta fios pela<NEXT>parte de trás e<NEXT>também pela boca.",["text2"]="É difícil saber<NEXT>qual ponta é qual."}}},{"ARTICUNO",{["value"]={["kind"]="GELO",["text"]="Dizem que as belas<NEXT>asas quase<NEXT>transparentes",["text2"]="desta ave lendária<NEXT>são feitas de<NEXT>gelo."}}},{"AZUMARILL",{["value"]={["kind"]="COELHO ÁGUA",["text"]="Fica parado e ouve<NEXT>com atenção para<NEXT>saber o que há até",["text2"]="em rios de<NEXT>correnteza forte."}}},{"BAYLEEF",{["value"]={["kind"]="FOLHA",["text"]="Um cheiro de<NEXT>especiarias vem de<NEXT>seu pescoço. Por",["text2"]="algum motivo,<NEXT>senti-lo dá<NEXT>vontade de lutar."}}},{"BEEDRILL",{["value"]={["kind"]="ABELHA VEN.",["text"]="Seus fortes<NEXT>ferrões venenosos<NEXT>derrubam qualquer",["text2"]="rival. Às vezes<NEXT>ataca em enxames."}}},{"BELLOSSOM",{["value"]={["kind"]="FLOR",["text"]="Às vezes,<NEXT>reúnem-se e<NEXT>parecem dançar.",["text2"]="Dizem que a dança<NEXT>é um ritual para<NEXT>invocar o sol."}}},{"BELLSPROUT",{["value"]={["kind"]="FLOR",["text"]="Embora seu corpo<NEXT>seja muito fino, é<NEXT>veloz como um raio",["text2"]="ao pegar presas."}}},{"BLASTOISE",{["value"]={["kind"]="MARISCO",["text"]="Torna seu corpo<NEXT>pesado de<NEXT>propósito para",["text2"]="resistir ao recuo<NEXT>dos jatos de água<NEXT>que dispara."}}},{"BLISSEY",{["value"]={["kind"]="FELICIDADE",["text"]="Quem prova até um<NEXT>pedaço de seu ovo<NEXT>passa a tratar",["text2"]="todos com carinho<NEXT>e gentileza."}}},{"BULBASAUR",{["value"]={["kind"]="SEMENTE",["text"]="A semente nas<NEXT>costas é rica em<NEXT>nutrientes. Ela",["text2"]="aumenta junto com<NEXT>seu corpo."}}},{"BUTTERFREE",{["value"]={["kind"]="BORBOLETA",["text"]="Coleta mel todo<NEXT>dia. Esfrega o mel<NEXT>nos pelos das",["text2"]="pernas para<NEXT>levá-lo ao ninho."}}},{"CATERPIE",{["value"]={["kind"]="LAGARTA",["text"]="Para se proteger,<NEXT>exala um fedor<NEXT>horrível pela",["text2"]="antena da cabeça e<NEXT>afasta os<NEXT>inimigos."}}},{"CELEBI",{["value"]={["kind"]="VIAJA-TEMPO",["text"]="Este POKéMON viaja<NEXT>pelo tempo.<NEXT>Árvores e grama",["text2"]="florescem nas<NEXT>florestas em que<NEXT>aparece."}}},{"CHANSEY",{["value"]={["kind"]="OVO",["text"]="Anda com cuidado<NEXT>para não quebrar<NEXT>seu ovo. Porém,",["text2"]="corre muito rápido<NEXT>quando precisa<NEXT>fugir."}}},{"CHARIZARD",{["value"]={["kind"]="CHAMA",["text"]="Quando fica<NEXT>furioso, a chama<NEXT>na ponta da cauda",["text2"]="arde num tom azul<NEXT>esbranquiçado."}}},{"CHARMANDER",{["value"]={["kind"]="LAGARTO",["text"]="A chama da cauda<NEXT>mostra sua força<NEXT>vital. Se estiver",["text2"]="fraco, ela também<NEXT>arde fraca."}}},{"CHARMELEON",{["value"]={["kind"]="CHAMA",["text"]="Por ser