ANTURN",{["value"]={["kind"]="LUZ",["text"]="Sua luz é tão<NEXT>forte que ilumina<NEXT>a superfície do",["text2"]="mar a mais de<NEXT>cinco quilômetros<NEXT>de profundidade."}}},{"LAPRAS",{["value"]={["kind"]="TRANSPORTE",["text"]="São dóceis e quase<NEXT>não lutam. Muitos<NEXT>foram capturados,",["text2"]="e sua população<NEXT>diminuiu."}}},{"LARVITAR",{["value"]={["kind"]="PELE ROCHA",["text"]="Alimenta-se de<NEXT>terra. Após comer<NEXT>uma montanha",["text2"]="grande, adormece<NEXT>para poder<NEXT>crescer."}}},{"LEDIAN",{["value"]={["kind"]="CINCO EST.",["text"]="Quando as estrelas<NEXT>piscam no céu<NEXT>noturno, voa por",["text2"]="aí espalhando um<NEXT>pó brilhante."}}},{"LEDYBA",{["value"]={["kind"]="CINCO EST.",["text"]="É muito tímido. Se<NEXT>está só, tem medo<NEXT>de se mover. Mas",["text2"]="fica ativo quando<NEXT>está em grupo."}}},{"LICKITUNG",{["value"]={["kind"]="LAMBEDOR",["text"]="Sua língua tem<NEXT>nervos bem<NEXT>desenvolvidos até",["text2"]="a ponta. Por isso,<NEXT>pode movê-la com<NEXT>destreza."}}},{"LUGIA",{["value"]={["kind"]="MERGULHO",["text"]="Dizem que vive<NEXT>quieto no fundo do<NEXT>mar porque seus",["text2"]="poderes são fortes<NEXT>demais."}}},{"MACHAMP",{["value"]={["kind"]="SUPERFORTE",["text"]="Agita os quatro<NEXT>braços e atinge<NEXT>rivais com socos e",["text2"]="golpes sem parar,<NEXT>vindos de todos os<NEXT>lados."}}},{"MACHOKE",{["value"]={["kind"]="SUPERFORTE",["text"]="Sempre usa toda a<NEXT>força. Mesmo<NEXT>assim, este",["text2"]="POKéMON tão<NEXT>resistente nunca<NEXT>se cansa."}}},{"MACHOP",{["value"]={["kind"]="SUPERFORTE",["text"]="Cheio de energia,<NEXT>passa o tempo<NEXT>erguendo rochas.",["text2"]="Isso o deixa ainda<NEXT>mais forte."}}},{"MAGBY",{["value"]={["kind"]="BRASA",["text"]="A cada inspiração<NEXT>e expiração,<NEXT>brasas quentes",["text2"]="caem de sua boca e<NEXT>de suas narinas."}}},{"MAGCARGO",{["value"]={["kind"]="LAVA",["text"]="A concha nas<NEXT>costas é só pele<NEXT>que esfriou e",["text2"]="endureceu. Quebra<NEXT>facilmente ao<NEXT>menor toque."}}},{"MAGIKARP",{["value"]={["kind"]="PEIXE",["text"]="É fraco e<NEXT>patético.<NEXT>Raramente dá um",["text2"]="salto alto, mas<NEXT>nunca passa de<NEXT>dois metros."}}},{"MAGMAR",{["value"]={["kind"]="COSPE-FOGO",["text"]="Não gosta de frio.<NEXT>Sopra chamas<NEXT>ardentes para",["text2"]="deixar o ambiente<NEXT>a seu gosto."}}},{"MAGNEMITE",{["value"]={["kind"]="ÍMÃ",["text"]="Ondas<NEXT>eletromagnéticas o<NEXT>atraem. Pode se",["text2"]="aproximar de<NEXT>Treinadores que<NEXT>usam POKéGEAR."}}},{"MAGNETON",{["value"]={["kind"]="ÍMÃ",["text"]="Três MAGNEMITE se<NEXT>unem por uma forte<NEXT>atração magnética.",["text2"]="Chegar perto causa<NEXT>dor de ouvido."}}},{"MANKEY",{["value"]={["kind"]="PORCO-SÍMIO",["text"]="Tem um péssimo<NEXT>humor. Em grupo,<NEXT>ataca sem motivo",["text2"]="qualquer alvo que<NEXT>esteja por perto."}}},{"MANTINE",{["value"]={["kind"]="PIPA",["text"]="Nada com majestade<NEXT>e não liga se<NEXT>REMORAID se",["text2"]="prendem ao seu<NEXT>corpo para comer<NEXT>suas sobras."}}},{"MAREEP",{["value"]={["kind"]="LÃ",["text"]="Se acumula<NEXT>eletricidade<NEXT>estática, sua lã",["text2"]="dobra de volume.<NEXT>Tocá-lo dá choque."}}},{"MARILL",{["value"]={["kind"]="RATO D'ÁGUA",["text"]="A ponta da cauda<NEXT>tem óleo mais leve<NEXT>que a água. Assim,",["text2"]="nada sem se<NEXT>afogar."}}},{"MAROWAK",{["value"]={["kind"]="GUARDA-OSSO",["text"]="Já foi visto<NEXT>batendo seu osso<NEXT>em rochas para",["text2"]="enviar mensagens a<NEXT>outros."}}},{"MEGANIUM",{["value"]={["kind"]="ERVA",["text"]="O aroma de suas<NEXT>pétalas contém uma<NEXT>substância que",["text2"]="acalma sentimentos<NEXT>agressivos."}}},{"MEOWTH",{["value"]={["kind"]="ARRANHADOR",["text"]="É fascinado por<NEXT>objetos redondos.<NEXT>Brinca com eles",["text2"]="sem parar até<NEXT>cansar e dormir."}}},{"METAPOD",{["value"]={["kind"]="CASULO",["text"]="Imóvel no casulo,<NEXT>seu corpo mole e<NEXT>fraco se prepara",["text2"]="para evoluir."}}},{"MEW",{["value"]={["kind"]="NOVA ESP.",["text"]="Parece surgir só<NEXT>para pessoas de<NEXT>coração puro que",["text2"]="têm um grande<NEXT>desejo de vê-lo."}}},{"MEWTWO",{["value"]={["kind"]="GENÉTICO",["text"]="Suas habilidades<NEXT>de combate foram<NEXT>elevadas ao",["text2"]="máximo. Só pensa<NEXT>em derrotar os<NEXT>rivais."}}},{"MILTANK",{["value"]={["kind"]="VACA LEITE",["text"]="Seu leite é tão<NEXT>nutritivo que é a<NEXT>bebida ideal para",["text2"]="quem está doente<NEXT>ou cansado."}}},{"MISDREAVUS",{["value"]={["kind"]="GRITO",["text"]="Gosta de<NEXT>travessuras, como<NEXT>gritar e gemer",["text2"]="para assustar<NEXT>pessoas durante a<NEXT>noite."}}},{"MOLTRES",{["value"]={["kind"]="CHAMA",["text"]="Espalha brasas a<NEXT>cada bater de<NEXT>asas. Ver este",["text2"]="POKéMON lendário é<NEXT>emocionante."}}},{"MR__MIME",{["value"]={["kind"]="BARREIRA",["text"]="Já nasce um mímico<NEXT>habilidoso. Ao<NEXT>crescer, adquire o",["text2"]="poder de criar<NEXT>objetos<NEXT>invisíveis."}}},{"MUK",{["value"]={["kind"]="LODO",["text"]="Adoram se reunir<NEXT>onde há lodo e mau<NEXT>cheiro, piorando",["text2"]="ainda mais o fedor<NEXT>nesses locais."}}},{"MURKROW",{["value"]={["kind"]="ESCURIDÃO",["text"]="Muitos o temem e<NEXT>odeiam.<NEXT>Acredita-se que",["text2"]="traz azar a quem o<NEXT>vê à noite."}}},{"NATU",{["value"]={["kind"]="PASSARINHO",["text"]="Suas asas ainda<NEXT>não cresceram bem,<NEXT>então se move aos",["text2"]="pulos. Sempre olha<NEXT>fixamente para<NEXT>algo."}}},{"NIDOKING",{["value"]={["kind"]="BROCA",["text"]="Na luta, agita sua<NEXT>cauda grande. Se o<NEXT>rival hesitar,",["text2"]="investe com seu<NEXT>corpo robusto."}}},{"NIDOQUEEN",{["value"]={["kind"]="BROCA",["text"]="Seu corpo tem<NEXT>escamas como<NEXT>agulhas. Nunca",["text2"]="demonstra medo<NEXT>diante de qualquer<NEXT>ataque."}}},{"NIDORAN_F",{["value"]={["kind"]="ESPINHO VEN",["text"]="O veneno do chifre<NEXT>pequeno é tão<NEXT>potente que até um",["text2"]="leve arranhão pode<NEXT>ser fatal."}}},{"NIDORAN_M",{["value"]={["kind"]="ESPINHO VEN",["text"]="É pequeno, mas seu<NEXT>chifre tem veneno.<NEXT>Avança e perfura",["text2"]="com ele para<NEXT>injetar a toxina."}}},{"NIDORINA",{["value"]={["kind"]="ESPINHO VEN",["text"]="Ao alimentar os<NEXT>filhotes, mastiga<NEXT>e amacia a comida",["text2"]="antes de cuspi-la<NEXT>para eles."}}},{"NIDORINO",{["value"]={["kind"]="ESPINHO VEN",["text"]="Ergue as orelhas<NEXT>grandes para<NEXT>examinar os",["text2"]="arredores. Se<NEXT>notar algo, ataca<NEXT>na hora."}}},{"NINETALES",{["value"]={["kind"]="RAPOSA",["text"]="Dizem as lendas<NEXT>que cada uma das<NEXT>nove caudas tem um",["text2"]="poder místico<NEXT>especial distinto."}}},{"NOCTOWL",{["value"]={["kind"]="CORUJA",["text"]="Seus olhos<NEXT>especiais<NEXT>concentram até a",["text2"]="luz mais fraca.<NEXT>Assim, consegue<NEXT>ver no escuro."}}},{"OCTILLERY",{["value"]={["kind"]="JATO",["text"]="Prende os rivais<NEXT>com as ventosas<NEXT>dos tentáculos e",["text2"]="os golpeia com a<NEXT>cabeça dura como<NEXT>pedra."}}},{"ODDISH",{["value"]={["kind"]="ERVA",["text"]="A luz da lua o<NEXT>desperta. Vaga<NEXT>ativo à noite, mas",["text2"]="passa o dia quieto<NEXT>sob a terra."}}},{"OMANYTE",{["value"]={["kind"]="ESPIRAL",["text"]="Reviveu de um<NEXT>fóssil antigo. Usa<NEXT>o ar na concha",["text2"]="para subir e<NEXT>afundar na água."}}},{"OMASTAR",{["value"]={["kind"]="ESPIRAL",["text"]="Parece que<NEXT>quebrava a concha<NEXT>de SHELLDER com",["text2"]="presas afiadas e<NEXT>sugava seu<NEXT>interior."}}},{"ONIX",{["value"]={["kind"]="SERP. PEDRA",["text"]="Serpenteia sob o<NEXT>solo. O estrondo<NEXT>de seus túneis",["text2"]="ecoa a uma grande<NEXT>distância."}}},{"PARAS",{["value"]={["kind"]="COGUMELO",["text"]="Ao nascer, recebe<NEXT>esporos de<NEXT>cogumelo.",["text2"]="Cogumelos brotam<NEXT>nas costas<NEXT>conforme cresce."}}},{"PARASECT",{["value"]={["kind"]="COGUMELO",["text"]="Vive em locais<NEXT>escuros e úmidos<NEXT>por gosto dos",["text2"]="grandes cogumelos<NEXT>nas costas, não do<NEXT>inseto."}}},{"PERSIAN",{["value"]={["kind"]="GATO FINO",["text"]="Muitos o adoram<NEXT>por seu ar<NEXT>refinado. Mas",["text2"]="ataca e arranha<NEXT>por quase nada."}}},{"PHANPY",{["value"]={["kind"]="TROMBA",["text"]="Balança a longa<NEXT>tromba por<NEXT>diversão. Porém,",["text2"]="sua grande força<NEXT>torna isso<NEXT>perigoso."}}},{"PICHU",{["value"]={["kind"]="RATINHO",["text"]="Ainda não sabe<NEXT>guardar bem a<NEXT>eletricidade. Pode",["text2"]="dar um choque se<NEXT>ficar alegre ou<NEXT>assustado."}}},{"PIDGEOT",{["value"]={["kind"]="PÁSSARO",["text"]="Seus fortes<NEXT>músculos do peito<NEXT>geram ventanias",["text2"]="com poucas batidas<NEXT>de asas."}}},{"PIDGEOTTO",{["value"]={["kind"]="PÁSSARO",["text"]="Sua visão é ótima.<NEXT>Por mais alto que<NEXT>voe, distingue os",["text2"]="movimentos de suas<NEXT>presas."}}},{"PIDGEY",{["value"]={["kind"]="PASSARINHO",["text"]="Costuma se ocultar<NEXT>no mato alto. Não<NEXT>gosta de lutar e",["text2"]="se protege<NEXT>levantando areia."}}},{"PIKACHU",{["value"]={["kind"]="RATO",["text"]="É inteligente.<NEXT>Assa FRUTAS duras<NEXT>com eletricidade",["text2"]="para amaciá-las e<NEXT>poder comê-las."}}},{"PILOSWINE",{["value"]={["kind"]="SUÍNO",["text"]="Os longos pelos de<NEXT>seu corpo tapam<NEXT>sua visão. Por",["text2"]="isso, só fica<NEXT>investindo sem<NEXT>parar."}}},{"PINECO",{["value"]={["kind"]="BICHO-CESTO",["text"]="Engrossa a concha<NEXT>juntando camadas<NEXT>de casca de",["text2"]="árvore. O peso<NEXT>extra não o<NEXT>incomoda."}}},{"PINSIR",{["value"]={["kind"]="BESOURO",["text"]="Cava tocas com os<NEXT>chifres para<NEXT>dormir à noite. De",["text2"]="manhã, terra úmida<NEXT>fica presa ao<NEXT>corpo."}}},{"POLITOED",{["value"]={["kind"]="SAPO",["text"]="Se POLIWAG e<NEXT>POLIWHIRL ouvem<NEXT>seu grito ecoar,",["text2"]="vêm de toda parte<NEXT>para se reunir."}}},{"POLIWAG",{["value"]={["kind"]="GIRINO",["text"]="Ainda não anda bem<NEXT>com as pernas<NEXT>recém-crescidas.",["text2"]="Por isso, vive<NEXT>nadando na água."}}},{"POLIWHIRL",{["value"]={["kind"]="GIRINO",["text"]="A espiral em sua<NEXT>barriga ondula de<NEXT>leve. Olhá-la pode",["text2"]="causar sono aos<NEXT>poucos."}}},{"POLIWRATH",{["value"]={["kind"]="GIRINO",["text"]="É tão forte e<NEXT>hábil na água que<NEXT>pode cruzar o",["text2"]="Oceano Pacífico só<NEXT>batendo as pernas."}}},{"PONYTA",{["value"]={["kind"]="CAVALO FOGO",["text"]="Ao nascer, corre<NEXT>mal. Ganha rapidez<NEXT>aos poucos ao",["text2"]="perseguir seus<NEXT>pais."}}},{"PORYGON",{["value"]={["kind"]="VIRTUAL",["text"]="É um POKéMON<NEXT>artificial. Como<NEXT>não respira,",["text2"]="querem testá-lo em<NEXT>qualquer ambiente."}}},{"PORYGON2",{["value"]={["kind"]="VIRTUAL",["text"]="Esta versão<NEXT>melhorada de<NEXT>PORYGON foi feita",["text2"]="para explorar o<NEXT>espaço. Porém, não<NEXT>pode voar."}}},{"PRIMEAPE",{["value"]={["kind"]="PORCO-SÍMIO",["text"]="Se chegar perto<NEXT>enquanto dorme,<NEXT>pode acordar e",["text2"]="persegui-lo<NEXT>furioso, ainda<NEXT>meio adormecido."}}},{"PSYDUCK",{["value"]={["kind"]="PATO",["text"]="Tem poderes<NEXT>místicos, mas não<NEXT>se lembra de",["text2"]="usá-los. Por isso,<NEXT>sempre parece<NEXT>confuso."}}},{"PUPITAR",{["value"]={["kind"]="CASCO DURO",["text"]="Sua casca é dura<NEXT>como rocha, e ele<NEXT>é muito forte. Ao",["text2"]="se debater, pode<NEXT>derrubar uma<NEXT>montanha."}}},{"QUAGSIRE",{["value"]={["kind"]="PEIXE ÁGUA",["text"]="É tranquilo e<NEXT>despreocupado. Ao<NEXT>nadar, vive",["text2"]="batendo nos cascos<NEXT>dos barcos."}}},{"QUILAVA",{["value"]={["kind"]="VULCÃO",["text"]="Cuidado se virar<NEXT>as costas na<NEXT>batalha. Isso",["text2"]="indica que vai<NEXT>atacar com o fogo<NEXT>nas costas."}}},{"QWILFISH",{["value"]={["kind"]="BALÃO",["text"]="Para lançar seus<NEXT>espinhos<NEXT>venenosos, infla o",["text2"]="corpo bebendo dez<NEXT>litros de água de<NEXT>uma vez."}}},{"RAICHU",{["value"]={["kind"]="RATO",["text"]="O acúmulo de<NEXT>eletricidade<NEXT>estimula seus",["text2"]="músculos e o torna<NEXT>mais agressivo que<NEXT>o normal."}}},{"RAIKOU",{["value"]={["kind"]="TROVÃO",["text"]="As nuvens que leva<NEXT>permitem lançar<NEXT>raios à vontade.",["text2"]="Dizem que desceu<NEXT>junto de um raio."}}},{"RAPIDASH",{["value"]={["kind"]="CAVALO FOGO",["text"]="No galope máximo,<NEXT>seus quatro cascos<NEXT>mal tocam o chão,",["text2"]="tamanha é sua<NEXT>velocidade."}}},{"RATICATE",{["value"]={["kind"]="RATO",["text"]="Rói tudo com suas<NEXT>presas fortes.<NEXT>Pode até derrubar",["text2"]="prédios de<NEXT>concreto ao<NEXT>roê-los."}}},{"RATTATA",{["value"]={["kind"]="RATO",["text"]="Come de tudo. Onde<NEXT>há comida, se<NEXT>instala e tem",["text2"]="filhotes sem<NEXT>parar."}}},{"REMORAID",{["value"]={["kind"]="JATO",["text"]="Sua mira é ótima.<NEXT>Atinge até presas<NEXT>em movimento com",["text2"]="jatos de água a<NEXT>mais de 90 metros."}}},{"RHYDON",{["value"]={["kind"]="BROCA",["text"]="Sua pele grossa o<NEXT>protege até do<NEXT>calor da lava, mas",["text2"]="também o torna<NEXT>insensível."}}},{"RHYHORN",{["value"]={["kind"]="ESPINHOS",["text"]="As quatro pernas<NEXT>curtas dificultam<NEXT>as curvas. Só pode",["text2"]="investir e correr<NEXT>numa direção."}}},{"SANDSHREW",{["value"]={["kind"]="RATO",["text"]="Se cair de muito<NEXT>alto, pode se<NEXT>salvar enrolando o",["text2"]="corpo como uma<NEXT>bola e quicando."}}},{"SANDSLASH",{["value"]={["kind"]="RATO",["text"]="Para se esconder,<NEXT>corre a toda força<NEXT>e levanta uma",["text2"]="nuvem de poeira<NEXT>que cega os<NEXT>rivais."}}},{"SCIZOR",{["value"]={["kind"]="TESOURA",["text"]="Ergue pinças com<NEXT>desenhos de olhos<NEXT>para assustar",["text2"]="rivais. Assim,<NEXT>parece ter três<NEXT>cabeças."}}},{"SCYTHER",{["value"]={["kind"]="LOUVA-DEUS",["text"]="Corta o mato com<NEXT>suas foices<NEXT>afiadas, rápido",["text2"]="demais para os<NEXT>olhos humanos<NEXT>acompanharem."}}},{"SEADRA